import { getAssetHostForServices } from 'config/api';

const host = getAssetHostForServices();

export const PERFORMANCE_AND_BREAKDOWN_BRANDS = {
  corona: `${host}/brands/corona/square.png`,
  budweiser: `${host}/brands/budweiser/square.png`,
  michelob: `${host}/brands/michelob/square.png`,
  stella_artois: `${host}/brands/stella_artois/square.png`,
  victoria: `${host}/brands/victoria/square.png`,
  bud_light: `${host}/brands/bud_light/square.png`,
  modelo: `${host}/brands/modelo/square.png`,
  pilsen: `${host}/brands/pilsen/square.png`,
  brahma: `${host}/brands/brahma/square.png`,
  busch: `${host}/brands/busch/square.png`,
  aguila: `${host}/brands/aguila/square.png`,
  carling: `${host}/brands/carling/square.png`,
  skol: `${host}/brands/skol/square.png`,
  others: `${host}/brands/other/square.png`,
} as const;

export type PerformanceAndBreakdownBrandImageKey =
  keyof typeof PERFORMANCE_AND_BREAKDOWN_BRANDS;

export const PERFORMANCE_AND_BREAKDOWN_BRAND_IMAGE_BY_NAME: Record<
  string,
  PerformanceAndBreakdownBrandImageKey
> = {
  Brahma: 'brahma',
  'Stella Artois': 'stella_artois',
  Skol: 'skol',
  Budweiser: 'budweiser',
  Corona: 'corona',
  'Bud Light': 'bud_light',
  Busch: 'busch',
  Michelob: 'michelob',
  Modelo: 'modelo',
  Victoria: 'victoria',
  Aguila: 'aguila',
  Pilsen: 'pilsen',
  Quilmes: 'pilsen',
  Leffe: 'stella_artois',
};

export function getPerformanceAndBreakdownBrandImageKey(
  brandName: string,
): PerformanceAndBreakdownBrandImageKey {
  return PERFORMANCE_AND_BREAKDOWN_BRAND_IMAGE_BY_NAME[brandName] ?? 'others';
}

export function getPerformanceAndBreakdownBrandImage(brandName: string): {
  src: string;
  alt: string;
} {
  const imageKey = getPerformanceAndBreakdownBrandImageKey(brandName);

  return {
    src: PERFORMANCE_AND_BREAKDOWN_BRANDS[imageKey],
    alt: brandName,
  };
}
